# RECOMPUTED with correct rule: start from lower cell, extend in direction of pair delta
import json

H, W = 13, 23
output = [[2] * W for _ in range(H)]

test_colors = {
    8: [(2,14), (3,15)],   # lower = (3,15), direction (+1,+1)
    7: [(2,17), (3,16)],   # lower = (3,16), direction (+1,-1)
    5: [(4,15), (5,14)],   # lower = (5,14), direction (+1,-1)
    3: [(4,16), (5,17)]   # lower = (5,17), direction (+1,+1)
}

# First, place all input cells
for color, positions in test_colors.items():
    for r, c in positions:
        output[r][c] = color

# Process each color, extend from lower cell
for color, positions in test_colors.items():
    pos_sorted = sorted(positions, key=lambda p: p[0])  # Upper cell first
    lower_cell = pos_sorted[1]  # Lower cell
    dr = pos_sorted[1][0] - pos_sorted[0][0]
    dc = pos_sorted[1][1] - pos_sorted[0][1]

    # Extend from lower cell in direction (dr, dc)
    start_r, start_c = lower_cell
    for i in range(0, H):
        r = start_r + dr * i
        c = start_c + dc * i
        if 0 <= r < H and 0 <= c < W:
            output[r][c] = color
        else:
            break

# Check overlap positions
print("Overlap positions (both 8 and 3 overlap):")
for r in range(H):
    for c in range(W):
        if output[r][c] in [3, 8]:
            if r >= 4:  # Focus on overlap area
                print(f"  ({r},{c}) = {output[r][c]}")

print("\nFinal output:")
for row in output:
    print(' '.join(str(x) for x in row))

